#!/usr/bin/env python3\n\"\"\"\nCelery Worker and Beat Startup Script\nFor running Celery tasks and scheduled jobs\n\"\"\"\n\nimport os\nimport sys\nimport subprocess\nimport signal\nimport time\nfrom multiprocessing import Process\n\ntry:\n    from celery import Celery\n    from celery.bin import worker, beat\n    CELERY_AVAILABLE = True\nexcept ImportError:\n    CELERY_AVAILABLE = False\n    print(\"❌ Celery not available. Install with: pip install celery redis\")\n    sys.exit(1)\n\ndef start_worker():\n    \"\"\"Start Celery worker\"\"\"\n    print(\"🔧 Starting Celery worker...\")\n    os.system(\"celery -A celery_worker worker --loglevel=info --concurrency=2\")\n\ndef start_beat():\n    \"\"\"Start Celery beat scheduler\"\"\"\n    print(\"⏰ Starting Celery beat scheduler...\")\n    os.system(\"celery -A celery_worker beat --loglevel=info\")\n\ndef start_flower():\n    \"\"\"Start Celery Flower monitoring (if available)\"\"\"\n    try:\n        print(\"🌸 Starting Celery Flower monitoring...\")\n        os.system(\"celery -A celery_worker flower --port=5555\")\n    except:\n        print(\"⚠️  Flower not available. Install with: pip install flower\")\n\ndef main():\n    if len(sys.argv) < 2:\n        print(\"\"\"\n🤖 Google Reviews Chatbot - Celery Management\n\nUsage:\n  python3 start_celery.py worker    # Start worker only\n  python3 start_celery.py beat      # Start beat scheduler only\n  python3 start_celery.py flower    # Start Flower monitoring\n  python3 start_celery.py all       # Start worker + beat\n  python3 start_celery.py monitor   # Start worker + beat + flower\n\nEnvironment Setup:\n  Make sure Redis is running: redis-server\n  Configure REDIS_URL in your .env file\n\nExample .env:\n  REDIS_URL=redis://localhost:6379/0\n  GOOGLE_API_KEY=your_key\n  OPENAI_API_KEY=your_key\n        \"\"\")\n        return\n    \n    command = sys.argv[1].lower()\n    \n    if not CELERY_AVAILABLE:\n        print(\"❌ Celery not installed. Run: pip install celery redis\")\n        return\n    \n    print(f\"🚀 Starting Celery services: {command}\")\n    \n    if command == \"worker\":\n        start_worker()\n    elif command == \"beat\":\n        start_beat()\n    elif command == \"flower\":\n        start_flower()\n    elif command == \"all\":\n        # Start worker and beat in parallel\n        worker_process = Process(target=start_worker)\n        beat_process = Process(target=start_beat)\n        \n        worker_process.start()\n        beat_process.start()\n        \n        try:\n            worker_process.join()\n            beat_process.join()\n        except KeyboardInterrupt:\n            print(\"\\n🛑 Stopping Celery services...\")\n            worker_process.terminate()\n            beat_process.terminate()\n    elif command == \"monitor\":\n        # Start all services\n        worker_process = Process(target=start_worker)\n        beat_process = Process(target=start_beat)\n        flower_process = Process(target=start_flower)\n        \n        worker_process.start()\n        beat_process.start()\n        flower_process.start()\n        \n        try:\n            worker_process.join()\n            beat_process.join()\n            flower_process.join()\n        except KeyboardInterrupt:\n            print(\"\\n🛑 Stopping all services...\")\n            worker_process.terminate()\n            beat_process.terminate()\n            flower_process.terminate()\n    else:\n        print(f\"❌ Unknown command: {command}\")\n        print(\"Valid commands: worker, beat, flower, all, monitor\")\n\nif __name__ == '__main__':\n    main()\n
